import {validLandmark} from './landmarks.mjs?v=20261007-r10';
import {initial,build,advance,score} from './game.mjs?v=20261007-r10';
import {cleanName} from './letters.mjs?v=20261007-r10';
const codes=['forest','solar','homes','wetland'];
function validateName(s){if(typeof s!=='string'||s.length>40||cleanName(s)!==s)throw Error('Invalid gift name.');return s;}
function reconstruct(history){if(!Array.isArray(history)||history.length>6)throw Error('Invalid city history.');const state=initial(),frames=[structuredClone(state)];for(const event of history){if(!Array.isArray(event)||event.length!==3||!event.every(Number.isInteger))throw Error('Invalid city action.');const [year,district,code]=event;if(year<state.year||year>2057||district<0||district>5||code<0||code>3)throw Error('Invalid city action.');while(state.year<year){advance(state);frames.push(structuredClone(state));}build(state,district,codes[code]);frames.push(structuredClone(state));}while(!state.ended){advance(state);frames.push(structuredClone(state));}return {state,frames};}
export function encodeGift(state,{to='',from='',landmark=null}={}){if(!state.ended)throw Error('Finish your city in 2058 before sending it.');const h=state.history.map(e=>[...e]);const replay=reconstruct(h).state;if(JSON.stringify(replay.plots)!==JSON.stringify(state.plots)||score(replay)!==score(state))throw Error('This city cannot be reconstructed.');if(!validLandmark(landmark))throw Error('Invalid landmark.');const payload={v:2,l:landmark,t:cleanName(to),f:cleanName(from),h,p:state.plots.map(p=>p===null?-1:codes.indexOf(p)),s:score(state)};const bytes=new TextEncoder().encode(JSON.stringify(payload));let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return '#gift='+btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
export function decodeGift(fragment){if(typeof fragment!=='string'||fragment.length>2048||!/^#gift=[A-Za-z0-9_-]+$/.test(fragment))throw Error('This gift link is incomplete or invalid.');let data;try{let raw=fragment.slice(6).replace(/-/g,'+').replace(/_/g,'/');raw+='='.repeat((4-raw.length%4)%4);const bytes=Uint8Array.from(atob(raw),c=>c.charCodeAt(0));data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch{throw Error('This gift link is incomplete or invalid.');}if(!data||Array.isArray(data)||![1,2].includes(data.v)||Object.keys(data).sort().join(',')!==(data.v===1?'f,h,p,s,t,v':'f,h,l,p,s,t,v')||(data.v===2&&!validLandmark(data.l)))throw Error('Unsupported gift format.');const to=validateName(data.t),from=validateName(data.f);if(!Array.isArray(data.p)||data.p.length!==6||!data.p.every(p=>Number.isInteger(p)&&p>=-1&&p<=3)||!Number.isInteger(data.s)||data.s<0||data.s>100)throw Error('Invalid city details.');const {state,frames}=reconstruct(data.h);if(JSON.stringify(state.plots.map(p=>p===null?-1:codes.indexOf(p)))!==JSON.stringify(data.p))throw Error('This gift does not match its city history.');return {to,from,state,frames,landmark:data.v===2?data.l:null};}
export function giftFrames(state){return reconstruct(state.history).frames;}
